// Accessible aerial fallback for browsers without WebGL. It does not claim to render 3D.
export class AerialFallback {
 constructor(canvas,{getCity,getImage,getCenter,getScenario,getMode,getWalkPos,getDistance,getLabels,bounds}){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.getCity=getCity;this.getImage=getImage;this.getCenter=getCenter;this.getScenario=getScenario;this.getMode=getMode;this.getWalkPos=getWalkPos;this.getDistance=getDistance;this.getLabels=getLabels;this.bounds=bounds;this.capabilities={getMaxAnisotropy:()=>1};this.shadowMap={};this.scissor=false;this.ratio=1;this.isFallback=true;}
 setPixelRatio(r){this.ratio=Math.min(r,1.5)}
 setSize(w,h){this.w=w;this.h=h;this.canvas.width=w*this.ratio;this.canvas.height=h*this.ratio;this.canvas.style.width=w+'px';this.canvas.style.height=h+'px'}
 setScissorTest(v){this.scissor=v}setScissor(x,y,w,h){this.sc={x,y,w,h}}
 clear(){this.ctx.clearRect(0,0,this.canvas.width,this.canvas.height)}
 render(){const ctx=this.ctx,d=this.getCity(),im=this.getImage(),s=this.getScenario(),c=this.getMode()==='walk'?this.getWalkPos():this.getCenter();if(!d||!im)return;const scale=Math.min(this.w,this.h)/(this.getMode()==='walk'?260:this.getDistance()*1.8);const X=x=>this.w*.48+(x-c.x)*scale,Z=z=>this.h*.5+(z-c.z)*scale;ctx.save();ctx.scale(this.ratio,this.ratio);if(this.scissor&&this.sc){ctx.beginPath();ctx.rect(this.sc.x,this.h-this.sc.y-this.sc.h,this.sc.w,this.sc.h);ctx.clip()}ctx.fillStyle='#647969';ctx.fillRect(0,0,this.w,this.h);ctx.drawImage(im,X(this.bounds.x0),Z(this.bounds.z0),(this.bounds.x1-this.bounds.x0)*scale,(this.bounds.z1-this.bounds.z0)*scale);const night=s.time<6||s.time>20;if(s.season==='winter'){ctx.fillStyle='#e1edefad';ctx.fillRect(0,0,this.w,this.h)}else if(s.season==='autumn'){ctx.fillStyle='#dc9a3333';ctx.fillRect(0,0,this.w,this.h)}if(night){ctx.fillStyle='#031932a6';ctx.fillRect(0,0,this.w,this.h)}
 if(s.streets!=='roads'){for(const r of d.roads){if(!['trunk','secondary','tertiary','residential'].includes(r.kind))continue;ctx.strokeStyle=s.streets==='pedestrian'?'#dcd0b1':s.streets==='cycle'?'#64b989':'#bcb793';ctx.lineWidth=(s.streets==='pedestrian'?10:2.5)*scale;ctx.beginPath();r.p.forEach((p,i)=>i?ctx.lineTo(X(p[0]),Z(p[1])):ctx.moveTo(X(p[0]),Z(p[1])));ctx.stroke();}}
 if(s.reclaim){ctx.fillStyle='#789759';for(const lot of d.parking||[]){ctx.beginPath();lot.p.forEach((p,i)=>i?ctx.lineTo(X(p[0]),Z(p[1])):ctx.moveTo(X(p[0]),Z(p[1])));ctx.closePath();ctx.fill()}}
 for(const b of d.buildings){if(Math.abs(X(b.c[0])-this.w/2)>this.w*.8||Math.abs(Z(b.c[1])-this.h/2)>this.h*.8)continue;const lift=(b.arch?.protected?0:s.height-1)*b.h*scale*.65;ctx.fillStyle=s.gardens?'#5b874c':'#d8d6c6';ctx.strokeStyle=night?'#d3e1b999':'#fff8';ctx.lineWidth=.55;ctx.beginPath();b.p.forEach((p,i)=>i?ctx.lineTo(X(p[0])+lift*.3,Z(p[1])-lift):ctx.moveTo(X(p[0])+lift*.3,Z(p[1])-lift));ctx.closePath();if(s.gardens||s.height!==1&&!b.arch?.protected)ctx.fill();ctx.stroke()}
 if(s.trees>30){ctx.fillStyle=s.season==='winter'?'#e6efe9':s.season==='autumn'?'#c58d34':'#426f39';for(const r of d.roads){if(!['trunk','tertiary','residential'].includes(r.kind))continue;for(let i=0;i<r.p.length-1;i++){const a=r.p[i],b=r.p[i+1],l=Math.hypot(b[0]-a[0],b[1]-a[1]);for(let t=10;t<l;t+=30){ctx.beginPath();ctx.arc(X(a[0]+(b[0]-a[0])*t/l)+7*scale,Z(a[1]+(b[1]-a[1])*t/l),3.5*scale,0,Math.PI*2);ctx.fill()}}}}
 for(const l of this.getLabels()){const x=X(l.p[0]),z=Z(l.p[1]);if(x<0||x>this.w||z<0||z>this.h)continue;ctx.font='11px system-ui';const w=ctx.measureText(l.name).width;ctx.fillStyle='#18342be6';ctx.fillRect(x-w/2-7,z-23,w+14,20);ctx.fillStyle='#f5ffe9';ctx.fillText(l.name,x-w/2,z-9)}
 if(s.fog){ctx.fillStyle='#d5e2e29a';ctx.fillRect(0,0,this.w,this.h)}ctx.fillStyle='#f2ffcf';ctx.strokeStyle='#173321';ctx.lineWidth=2;ctx.beginPath();ctx.arc(X(c.x),Z(c.z),5,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.restore();
 }
}
